from dataclasses import dataclass
from enum import Enum
from numbers import Real


class ExhibitKind(Enum):
    PHYSICAL = "physical"
    DIGITAL = "digital"


class ViewingMode(Enum):
    ONSITE = "onsite"
    REMOTE = "remote"


@dataclass(frozen=True)
class Exhibit:
    kind: ExhibitKind
    viewing_mode: ViewingMode
    catalog_id: str
    label: str
    creator: str
    list_fee: float
    current_fee: float
    reference: str
    raw: dict


def compile_exhibits(pages, kind, viewing_mode):
    if not isinstance(kind, ExhibitKind):
        raise TypeError("kind must be an ExhibitKind")
    if not isinstance(viewing_mode, ViewingMode):
        raise TypeError("viewing_mode must be a ViewingMode")
    try:
        iterator = iter(pages)
    except TypeError as exc:
        raise TypeError("pages must be iterable") from exc

    result = []
    for page in iterator:
        if not isinstance(page, list):
            raise TypeError("each page must be a list")
        if not page:
            break
        for item in page:
            if not isinstance(item, dict):
                raise TypeError("each item must be a dictionary")
            for field in ("code", "label", "creator", "fees"):
                if field not in item:
                    raise ValueError("missing field: " + field)
            for field in ("code", "label", "creator"):
                if not isinstance(item[field], str):
                    raise TypeError(field + " must be a string")
            fees = item["fees"]
            if not isinstance(fees, dict):
                raise TypeError("fees must be a dictionary")
            for field in ("list", "current"):
                if field not in fees:
                    raise ValueError("missing fee: " + field)
                if isinstance(fees[field], bool) or not isinstance(fees[field], Real):
                    raise TypeError("fees must be numeric")
            code = item["code"]
            result.append(Exhibit(
                kind, viewing_mode, "archive:" + code, item["label"],
                item["creator"], float(fees["list"]), float(fees["current"]),
                "/exhibits/" + code, item
            ))
    return result

